import contextlib
import io
import json
import os
import subprocess
import sys
import tempfile
import unittest

from pennywise.cli import main

SAMPLE = (
    "# household, March\n"
    "2024-03-01 salary 2500.00 March pay\n"
    "2024-03-02 groceries -42.50 weekly shop\n"
    "\n"
    "2024-03-05 Rent -900\n"
)
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))


class FakeStdin(io.TextIOWrapper):
    def __init__(self, data):
        super().__init__(io.BytesIO(data), encoding="utf-8")


def run(argv, stdin=None):
    out, err = io.StringIO(), io.StringIO()
    old_stdin = sys.stdin
    if stdin is not None:
        sys.stdin = FakeStdin(stdin.encode("utf-8") if isinstance(stdin, str) else stdin)
    try:
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            code = main(argv)
    finally:
        sys.stdin = old_stdin
    return code, out.getvalue(), err.getvalue()


class CliCase(unittest.TestCase):
    def setUp(self):
        tmp = tempfile.TemporaryDirectory()
        self.addCleanup(tmp.cleanup)
        self.dir = tmp.name
        self.path = self.write("house.txt", SAMPLE)

    def write(self, name, text):
        path = os.path.join(self.dir, name)
        with open(path, "wb") as handle:
            handle.write(text if isinstance(text, bytes) else text.encode("utf-8"))
        return path

    def read(self, path=None):
        with open(path or self.path, "rb") as handle:
            return handle.read()

    def assertFails(self, argv, status, stdin=None):
        code, out, err = run(argv, stdin)
        self.assertEqual(code, status, err)
        self.assertEqual(out, "")
        self.assertTrue(err.startswith("pennywise: ") or status == 2, err)
        self.assertNotEqual(err, "")
        return err


class BalanceTests(CliCase):
    def test_balance(self):
        self.assertEqual(run(["balance", self.path]), (0, "1557.50\n", ""))

    def test_balance_json(self):
        code, out, _ = run(["balance", self.path, "--json"])
        self.assertEqual((code, json.loads(out)), (0, {"balance": "1557.50"}))

    def test_balance_empty_ledger(self):
        path = self.write("empty.txt", "")
        self.assertEqual(run(["balance", path]), (0, "0.00\n", ""))

    def test_balance_negative_zero(self):
        path = self.write("z.txt", "2024-01-01 a -0\n2024-01-01 b 0.00\n")
        self.assertEqual(run(["balance", path])[1], "0.00\n")


class SummaryTests(CliCase):
    def test_by_category_default(self):
        self.assertEqual(
            run(["summary", self.path]),
            (0, "groceries  -42.50\nrent  -900.00\nsalary  2500.00\n", ""),
        )

    def test_by_month(self):
        path = self.write("m.txt", "2024-04-01 a 1\n2024-03-01 a 2\n2024-03-09 b 3.5\n")
        self.assertEqual(
            run(["summary", path, "--by", "month"]),
            (0, "2024-03  5.50\n2024-04  1.00\n", ""),
        )

    def test_json_sorted_keys_and_strings(self):
        code, out, _ = run(["summary", self.path, "--json"])
        self.assertEqual(code, 0)
        self.assertEqual(out, '{"groceries": "-42.50", "rent": "-900.00", "salary": "2500.00"}\n')

    def test_empty_ledger(self):
        path = self.write("empty.txt", "# nothing\n")
        self.assertEqual(run(["summary", path]), (0, "", ""))
        self.assertEqual(run(["summary", path, "--json"]), (0, "{}\n", ""))

    def test_bad_by_value(self):
        self.assertFails(["summary", self.path, "--by", "year"], 2)


class ListTests(CliCase):
    def test_list(self):
        self.assertEqual(
            run(["list", self.path]),
            (
                0,
                "2024-03-01 salary 2500.00 March pay\n"
                "2024-03-02 groceries -42.50 weekly shop\n"
                "2024-03-05 rent -900.00\n",
                "",
            ),
        )

    def test_sorted_by_date_stable_within_day(self):
        path = self.write(
            "o.txt",
            "2024-03-02 b 2\n2024-03-01 z 9\n2024-03-02 a 1\n2024-03-02 c 3\n",
        )
        lines = run(["list", path])[1].splitlines()
        self.assertEqual(
            lines,
            ["2024-03-01 z 9.00", "2024-03-02 b 2.00", "2024-03-02 a 1.00", "2024-03-02 c 3.00"],
        )

    def test_filters(self):
        self.assertEqual(
            run(["list", self.path, "--category", "GROCERIES"])[1],
            "2024-03-02 groceries -42.50 weekly shop\n",
        )
        self.assertEqual(
            run(["list", self.path, "--since", "2024-03-02", "--until", "2024-03-02"])[1],
            "2024-03-02 groceries -42.50 weekly shop\n",
        )
        self.assertEqual(run(["list", self.path, "--since", "2024-03-03"])[1], "2024-03-05 rent -900.00\n")
        self.assertEqual(run(["list", self.path, "--until", "2024-03-01"])[1].count("\n"), 1)

    def test_json(self):
        code, out, _ = run(["list", self.path, "--json", "--category", "rent"])
        self.assertEqual(code, 0)
        self.assertEqual(
            out,
            '[{"date": "2024-03-05", "category": "rent", "amount": "-900.00", "note": ""}]\n',
        )

    def test_json_no_match(self):
        self.assertEqual(run(["list", self.path, "--json", "--category", "x"]), (0, "[]\n", ""))

    def test_bad_date_options(self):
        for opt in ("--since", "--until"):
            for bad in ("2024-02-30", "yesterday", "2024-3-1", ""):
                with self.subTest(opt=opt, bad=bad):
                    self.assertFails(["list", self.path, opt, bad], 2)


class ExportTests(CliCase):
    def test_csv(self):
        path = self.write("c.txt", '2024-03-02 a 1 say "hi", ok\n2024-03-01 b -2\n')
        self.assertEqual(
            run(["export", path]),
            (0, 'date,category,amount,note\n2024-03-01,b,-2.00,\n2024-03-02,a,1.00,"say ""hi"", ok"\n', ""),
        )
        self.assertEqual(run(["export", path, "--format", "csv"]), run(["export", path]))

    def test_csv_empty_has_header(self):
        path = self.write("e.txt", "")
        self.assertEqual(run(["export", path]), (0, "date,category,amount,note\n", ""))

    def test_bad_format(self):
        self.assertFails(["export", self.path, "--format", "xml"], 2)


class AddTests(CliCase):
    def test_add_appends_and_prints(self):
        code, out, err = run(["add", self.path, "2024-03-09", "Fun", "-5.5", "cinema  night"])
        self.assertEqual((code, out, err), (0, "2024-03-09 fun -5.50 cinema  night\n", ""))
        self.assertEqual(self.read(), SAMPLE.encode() + b"2024-03-09 fun -5.50 cinema  night\n")

    def test_add_no_note(self):
        code, out, _ = run(["add", self.path, "2024-03-09", "fun", "5"])
        self.assertEqual((code, out), (0, "2024-03-09 fun 5.00\n"))

    def test_add_creates_file(self):
        path = os.path.join(self.dir, "new.txt")
        self.assertEqual(run(["add", path, "2024-03-09", "fun", "5"])[0], 0)
        self.assertEqual(self.read(path), b"2024-03-09 fun 5.00\n")

    def test_add_adds_missing_newline(self):
        path = self.write("n.txt", "2024-03-01 a 1")
        run(["add", path, "2024-03-02", "b", "2"])
        self.assertEqual(self.read(path), b"2024-03-01 a 1\n2024-03-02 b 2.00\n")
        self.assertEqual(run(["balance", path])[1], "3.00\n")

    def test_add_to_empty_existing_file_no_leading_newline(self):
        path = self.write("e.txt", "")
        run(["add", path, "2024-03-02", "b", "2"])
        self.assertEqual(self.read(path), b"2024-03-02 b 2.00\n")

    def test_add_does_not_validate_existing_contents(self):
        path = self.write("bad.txt", "garbage\n")
        self.assertEqual(run(["add", path, "2024-03-02", "b", "2"])[0], 0)
        self.assertEqual(self.read(path), b"garbage\n2024-03-02 b 2.00\n")

    def test_invalid_entries_leave_file_unchanged(self):
        cases = [
            ["2024-02-30", "fun", "5"],
            ["nope", "fun", "5"],
            ["2024-03-09", "fun", "12.505"],
            ["2024-03-09", "fun", "abc"],
            ["2024-03-09", "fun", "1,000.00"],
            ["2024-03-09", "two words", "5"],
            ["2024-03-09", "fun", "5 x"],
            ["2024-03-09", "", "5"],
            ["2024-03-09", "fun", "5", "line\nbreak"],
            ["2024-03-09", "fun", "5", "cr\rhere"],
            ["#2024-03-09", "fun", "5"],
        ]
        for case in cases:
            with self.subTest(case=case):
